<?php
require __DIR__.'/includes/bootstrap.php';require_login();require_member($pdo);
function wedding_schema(PDO $db):void{
 $db->exec("CREATE TABLE IF NOT EXISTS wedding_guests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(220) NOT NULL, party_size SMALLINT UNSIGNED NOT NULL DEFAULT 1, table_name VARCHAR(100) NOT NULL DEFAULT '', response ENUM('Confirmat','Refuzat','Neconfirmat') NOT NULL DEFAULT 'Neconfirmat', attended TINYINT(1) NOT NULL DEFAULT 0, gift_amount DECIMAL(12,2) NULL, gift_currency ENUM('RON','EUR','USD','GBP') NOT NULL DEFAULT 'RON', notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_response(response),INDEX idx_name(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $db->exec("CREATE TABLE IF NOT EXISTS wedding_visits (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, guest_id INT UNSIGNED NULL, couple_name VARCHAR(220) NOT NULL, wedding_date DATE NULL, venue VARCHAR(220) NOT NULL DEFAULT '', status ENUM('De mers','Am fost','Anulată') NOT NULL DEFAULT 'De mers', gift_amount DECIMAL(12,2) NULL, gift_currency ENUM('RON','EUR','USD','GBP') NOT NULL DEFAULT 'RON', notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_status_date(status,wedding_date), INDEX idx_guest(guest_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
}
wedding_schema($pdo);
// Non-destructive migration for the personal follow-up status.
try {
 $cols=$pdo->query("SHOW COLUMNS FROM wedding_guests LIKE 'visit_status'")->fetchAll();
 if(!$cols){$pdo->exec("ALTER TABLE wedding_guests ADD COLUMN visit_status ENUM('','De mers','Nu mergem','Am fost noi','Au fost ai noștri') NOT NULL DEFAULT ''");}
} catch(Throwable $e){error_log('Wedding status migration: '.$e->getMessage());}

// Import once, guarded by a DB named lock to prevent duplicate records across simultaneous visits.
$importFile=CIOLTEA_SECURITY_DIR.'/wedding-guests-import.csv';
if(is_file($importFile)){
 try{
  $lock=(int)$pdo->query("SELECT GET_LOCK('cioltea_wedding_import', 3)")->fetchColumn();
  if($lock===1){
   if((int)$pdo->query('SELECT COUNT(*) FROM wedding_guests')->fetchColumn()===0){
    $handle=fopen($importFile,'rb');if($handle){
     $pdo->beginTransaction();try{
      fgetcsv($handle,0,',','"','\\');$ins=$pdo->prepare('INSERT INTO wedding_guests(name,party_size,table_name,response,attended,gift_amount,gift_currency) VALUES(?,?,?,?,?,?,?)');
      while(($r=fgetcsv($handle,0,',','"','\\'))!==false){if(count($r)<7||trim($r[0])==='')continue;$ins->execute([$r[0],max(1,(int)$r[1]),$r[2],in_array($r[3],['Confirmat','Refuzat'],true)?$r[3]:'Neconfirmat',(int)$r[4],$r[5]===''?null:$r[5],in_array($r[6],['RON','EUR','USD','GBP'],true)?$r[6]:'RON']);}
      $pdo->commit();@unlink($importFile);
     }catch(Throwable $e){$pdo->rollBack();error_log('Wedding import: '.$e->getMessage());}fclose($handle);
    }
   }else{@unlink($importFile);}
   $pdo->query("SELECT RELEASE_LOCK('cioltea_wedding_import')");
  }
 }catch(Throwable $e){error_log('Wedding import lock: '.$e->getMessage());}
}
$notice='';$error='';$tab=($_GET['tab']??'guests')==='visits'?'visits':'guests';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);$tab=($_POST['tab']??'guests')==='visits'?'visits':'guests';
 try{
  if(in_array($action,['guest_save','visit_save'],true)){
   $name=trim((string)($_POST['name']??''));if($name===''||mb_strlen($name)>220)throw new RuntimeException('Completează numele (maxim 220 caractere).');
   $currency=(string)($_POST['currency']??'RON');if(!in_array($currency,['RON','EUR','USD','GBP'],true))throw new RuntimeException('Monedă invalidă.');
   $giftRaw=trim(str_replace(',','.',(string)($_POST['gift_amount']??'')));if($giftRaw!==''&&(!is_numeric($giftRaw)||(float)$giftRaw<0||(float)$giftRaw>9999999999))throw new RuntimeException('Valoare cadou invalidă.');$gift=$giftRaw===''?null:round((float)$giftRaw,2);
   $notes=mb_substr(trim((string)($_POST['notes']??'')),0,4000);
   if($action==='guest_save'){
    $size=max(1,min(50,(int)($_POST['party_size']??1)));$table=mb_substr(trim((string)($_POST['table_name']??'')),0,100);$response=(string)($_POST['response']??'Neconfirmat');if(!in_array($response,['Confirmat','Refuzat','Neconfirmat'],true))throw new RuntimeException('Status invalid.');$attended=isset($_POST['attended'])?1:0;
    if($id){$s=$pdo->prepare('UPDATE wedding_guests SET name=?,party_size=?,table_name=?,response=?,attended=?,gift_amount=?,gift_currency=?,notes=? WHERE id=?');$s->execute([$name,$size,$table,$response,$attended,$gift,$currency,$notes,$id]);}else{$s=$pdo->prepare('INSERT INTO wedding_guests(name,party_size,table_name,response,attended,gift_amount,gift_currency,notes) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$name,$size,$table,$response,$attended,$gift,$currency,$notes]);}
   }else{
    $status=(string)($_POST['status']??'De mers');if(!in_array($status,['De mers','Am fost','Anulată'],true))throw new RuntimeException('Status invalid.');$date=trim((string)($_POST['wedding_date']??''));if($date!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||date('Y-m-d',strtotime($date))!==$date))throw new RuntimeException('Data nu este validă.');$date=$date?:null;$venue=mb_substr(trim((string)($_POST['venue']??'')),0,220);$guestId=(int)($_POST['guest_id']??0);if($guestId){$check=$pdo->prepare('SELECT COUNT(*) FROM wedding_guests WHERE id=?');$check->execute([$guestId]);if(!(int)$check->fetchColumn())throw new RuntimeException('Invitatul asociat nu există.');}else{$guestId=null;}
    if($id){$s=$pdo->prepare('UPDATE wedding_visits SET couple_name=?,wedding_date=?,venue=?,status=?,gift_amount=?,gift_currency=?,notes=?,guest_id=? WHERE id=?');$s->execute([$name,$date,$venue,$status,$gift,$currency,$notes,$guestId,$id]);}else{$s=$pdo->prepare('INSERT INTO wedding_visits(couple_name,wedding_date,venue,status,gift_amount,gift_currency,notes,guest_id) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$name,$date,$venue,$status,$gift,$currency,$notes,$guestId]);}
   }
   $notice='Salvat cu succes.';
  }elseif(in_array($action,['guest_delete','visit_delete'],true)&&$id){$table=$action==='guest_delete'?'wedding_guests':'wedding_visits';$pdo->prepare("DELETE FROM $table WHERE id=?")->execute([$id]);$notice='Înregistrare ștearsă.';}
  elseif($action==='visit_done'&&$id){$pdo->prepare("UPDATE wedding_visits SET status='Am fost' WHERE id=?")->execute([$id]);$notice='Marcată ca participată.';}
  elseif($action==='visit_reopen'&&$id){$pdo->prepare("UPDATE wedding_visits SET status='De mers' WHERE id=?")->execute([$id]);$notice='Revenită în lista de mers.';}
  elseif($action==='guest_visit_status'&&$id){
   $status=(string)($_POST['visit_status']??'');
   if(!in_array($status,['','De mers','Nu mergem','Am fost noi','Au fost ai noștri'],true))throw new RuntimeException('Status invalid.');
   $q=$pdo->prepare('SELECT name FROM wedding_guests WHERE id=?');$q->execute([$id]);$name=$q->fetchColumn();
   if($name===false)throw new RuntimeException('Invitatul nu există.');
   $pdo->prepare('UPDATE wedding_guests SET visit_status=? WHERE id=?')->execute([$status,$id]);
   $q=$pdo->prepare('SELECT id,status FROM wedding_visits WHERE guest_id=? ORDER BY id LIMIT 1');$q->execute([$id]);$existing=$q->fetch(PDO::FETCH_ASSOC);
   if($status==='De mers'){
    if($existing){$pdo->prepare("UPDATE wedding_visits SET status='De mers' WHERE id=?")->execute([$existing['id']]);}
    else{$pdo->prepare("INSERT INTO wedding_visits(guest_id,couple_name,status) VALUES(?,?,'De mers')")->execute([$id,$name]);}
   }elseif($existing){
    $newStatus=in_array($status,['Am fost noi','Au fost ai noștri'],true)?'Am fost':'Anulată';
    $pdo->prepare('UPDATE wedding_visits SET status=? WHERE id=?')->execute([$newStatus,$existing['id']]);
   }
   $notice='Status actualizat.';
  }
  elseif($action==='guest_visit'&&$id){$s=$pdo->prepare('SELECT name FROM wedding_guests WHERE id=?');$s->execute([$id]);$name=$s->fetchColumn();if(!$name)throw new RuntimeException('Invitatul nu există.');$pdo->prepare('INSERT INTO wedding_visits(guest_id,couple_name) VALUES(?,?)')->execute([$id,$name]);$tab='guests';$notice='Adăugat în lista nunților la care mergeți.';}
 }catch(Throwable $e){$error=$e->getMessage();}
}
$guests=$pdo->query('SELECT * FROM wedding_guests ORDER BY name ASC')->fetchAll();
$visits=$pdo->query('SELECT v.*,g.gift_amount AS their_gift,g.gift_currency AS their_currency,g.name AS guest_name FROM wedding_visits v LEFT JOIN wedding_guests g ON g.id=v.guest_id ORDER BY (v.status=\'De mers\') DESC, (v.wedding_date IS NULL) ASC,v.wedding_date ASC,v.couple_name ASC')->fetchAll();
$editId=(int)($_GET['edit']??0);$editing=null;
if($editId){foreach(($tab==='guests'?$guests:$visits) as $r){if((int)$r['id']===$editId){$editing=$r;break;}}}
$pageTitle='Nunți & invitați';$active='more';require __DIR__.'/includes/layout_top.php';
