<script>(function(){const input=document.getElementById('weddingSearch'),filter=document.getElementById('visitFilter'),hide=document.getElementById('hideRefused'),show=document.getElementById('showCompleted'),rows=[...document.querySelectorAll('.wedding-row')],empty=document.getElementById('weddingNoResults');function update(){let n=0;const q=(input?.value||'').toLocaleLowerCase('ro').trim();rows.forEach(r=>{const visible=(!q||r.dataset.name.includes(q))&&(!hide?.checked||r.dataset.refused!=='1')&&(!!show?.checked||r.dataset.completed!=='1')&&(!filter||filter.value==='all'||r.dataset.visitStatus===filter.value);r.hidden=!visible;if(visible)n++});if(empty)empty.hidden=n>0}input?.addEventListener('input',update);hide?.addEventListener('change',update);show?.addEventListener('change',update);filter?.addEventListener('change',()=>{sessionStorage.setItem('weddingVisitFilter',filter.value);update()});if(filter){const saved=sessionStorage.getItem('weddingVisitFilter');if(saved!==null&&[...filter.options].some(o=>o.value===saved))filter.value=saved}update()})();</script>
